WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating DESC, id) AS rank_in_group FROM suppliers) t WHERE rank_in_group = 1) SELECT CASE WHEN rating >= 3.6 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, ROUND(AVG(rating), 2) AS avg_rating, STDDEV_SAMP(rating) AS rating_stddev, MIN(rating) AS min_rating FROM latest GROUP BY CASE WHEN rating >= 3.6 THEN 'HIGH' ELSE 'LOW' END ORDER BY min_rating
